import { Avatar, AvatarImage } from "@/components/ui/avatar";
import { getAllPeople, getAvatarUrl, imageUrl } from "@/lib/demo-data";
import { ArrowDownRight, Star } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { AnimatedGroup } from "../shared/animated-group";
import { AnimatedText } from "../shared/animated-text";
import PressButton from "@/components/elements/press-button";
import { HeroHeader } from "../shared/hero-header";

interface HeroShowcaseProps {
  buttons?: {
    primary?: {
      text: string;
      url: string;
    };
    secondary?: {
      text: string;
      url: string;
    };
  };
  description?: string;
  heading?: string;
  reviews?: {
    count: number;
    avatars: {
      src: string;
      alt: string;
    }[];
    rating?: number;
  };
}

export function HeroShowcase({
  heading = "Build beautiful UIs, effortlessly.",
  description = "DX UI gives you the building blocks to create stunning, animated interfaces in minutes.",
  buttons = {
    primary: {
      text: "Get Started",
      url: "#link",
    },
    secondary: {
      text: "Watch demo",
      url: "#link",
    },
  },
  reviews = {
    avatars: getAllPeople()
      .slice(0, 5)
      .map((person) => ({
        alt: `${person.name} avatar`,
        src: getAvatarUrl(person.avatar, 90),
      })),
    count: 200,
    rating: 5.0,
  },
}: HeroShowcaseProps) {
  const shouldReduceMotion = useReducedMotion();
  return (
    <>
      <HeroHeader />
      <main>
        <motion.section
          animate={
            shouldReduceMotion
              ? { opacity: 1 }
              : { filter: "blur(0px)", opacity: 1, scale: 1 }
          }
          className="relative overflow-hidden bg-gradient-to-b from-background to-muted"
          initial={
            shouldReduceMotion
              ? { opacity: 1 }
              : { filter: "blur(12px)", opacity: 0, scale: 1.04 }
          }
          transition={
            shouldReduceMotion
              ? { duration: 0 }
              : { bounce: 0.32, duration: 0.9, type: "spring" as const }
          }
        >
          <div className="mx-auto grid max-w-5xl items-center gap-10 px-6 py-24 lg:grid-cols-2 lg:gap-20">
            <AnimatedGroup
              className="mx-auto flex flex-col items-center text-center md:ml-auto lg:max-w-3xl lg:items-start lg:text-left"
              preset="blur-slide"
            >
              <AnimatedText
                as="h1"
                className="my-6 text-pretty font-bold text-4xl lg:text-6xl xl:text-7xl"
              >
                {heading}
              </AnimatedText>
              <AnimatedText
                as="p"
                className="mb-8 max-w-xl text-foreground/70 lg:text-xl"
                delay={0.12}
              >
                {description}
              </AnimatedText>
              <AnimatedGroup
                className="mb-12 flex w-fit flex-col items-center gap-4 sm:flex-row"
                preset="slide"
              >
                <span className="inline-flex items-center -space-x-4">
                  {reviews.avatars.map((avatar, index) => (
                    <motion.div
                      key={`${avatar.src}-${index}`}
                      style={{ display: "inline-block" }}
                      transition={{
                        damping: 20,
                        stiffness: 300,
                        type: "spring" as const,
                      }}
                      whileHover={shouldReduceMotion ? {} : { y: -8 }}
                    >
                      <Avatar className="size-12 border">
                        <AvatarImage alt={avatar.alt} src={avatar.src} />
                      </Avatar>
                    </motion.div>
                  ))}
                </span>
                <div>
                  <div className="flex items-center gap-1">
                    {[1, 2, 3, 4, 5].map((starNumber) => (
                      <Star
                        className="size-5 fill-yellow-400 text-yellow-400"
                        key={`star-${starNumber}`}
                      />
                    ))}
                    <span className="mr-1 font-semibold">
                      {reviews.rating?.toFixed(1)}
                    </span>
                  </div>
                  <p className="text-left font-medium text-foreground/70">
                    from {reviews.count}+ reviews
                  </p>
                </div>
              </AnimatedGroup>
              <AnimatedGroup
                className="flex w-full flex-col justify-center gap-2 sm:flex-row lg:justify-start"
                preset="slide"
              >
                {buttons.primary ? (
                  <PressButton asChild className="w-full sm:w-auto" variant="candy">
                    <a href={buttons.primary.url}>{buttons.primary.text}</a>
                  </PressButton>
                ) : null}
                {buttons.secondary ? (
                  <PressButton asChild variant="outline">
                    <a href={buttons.secondary.url}>
                      {buttons.secondary.text}
                      <ArrowDownRight className="size-4" />
                    </a>
                  </PressButton>
                ) : null}
              </AnimatedGroup>
            </AnimatedGroup>
            {/* Imagen completamente estática para que el blend mode funcione perfecto */}
            <div className="flex">
              <img
                alt="app screen"
                className="h-full w-full rounded-md object-cover"
                draggable={false}
                height={1842}
                src={imageUrl("/images/dx/hero-settings.webp", {
                  format: "auto",
                  quality: 85,
                  width: 1200,
                })}
                width={2880}
              />
            </div>
          </div>
        </motion.section>
      </main>
    </>
  );
}
export default HeroShowcase;

import { motion, useReducedMotion, type Variants } from "motion/react";
import React, { type ReactNode } from "react";

export type PresetType =
  | "fade"
  | "slide"
  | "scale"
  | "blur"
  | "blur-slide"
  | "zoom"
  | "flip"
  | "bounce"
  | "rotate"
  | "swing";

export interface AnimatedGroupProps {
  as?: React.ElementType;
  asChild?: React.ElementType;
  children: ReactNode;
  className?: string;
  preset?: PresetType;
  variants?: {
    container?: Variants;
    item?: Variants;
  };
}

const defaultContainerVariants: Variants = {
  visible: {
    transition: {
      staggerChildren: 0.1,
    },
  },
};

const defaultItemVariants: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
};

const presetVariants: Record<PresetType, Variants> = {
  blur: {
    hidden: { filter: "blur(4px)" },
    visible: { filter: "blur(0px)" },
  },
  "blur-slide": {
    hidden: { filter: "blur(4px)", y: 20 },
    visible: { filter: "blur(0px)", y: 0 },
  },
  bounce: {
    hidden: { y: -50 },
    visible: {
      transition: { damping: 10, stiffness: 400, type: "spring" as const },
      y: 0,
    },
  },
  fade: {},
  flip: {
    hidden: { rotateX: -90 },
    visible: {
      rotateX: 0,
      transition: { damping: 20, stiffness: 300, type: "spring" as const },
    },
  },
  rotate: {
    hidden: { rotate: -180 },
    visible: {
      rotate: 0,
      transition: { damping: 15, stiffness: 200, type: "spring" as const },
    },
  },
  scale: {
    hidden: { scale: 0.8 },
    visible: { scale: 1 },
  },
  slide: {
    hidden: { y: 20 },
    visible: { y: 0 },
  },
  swing: {
    hidden: { rotate: -10 },
    visible: {
      rotate: 0,
      transition: { damping: 8, stiffness: 300, type: "spring" as const },
    },
  },
  zoom: {
    hidden: { scale: 0.5 },
    visible: {
      scale: 1,
      transition: { damping: 20, stiffness: 300, type: "spring" as const },
    },
  },
};

const reducedContainerVariants: Variants = {
  hidden: { opacity: 1 },
  visible: { opacity: 1, transition: { staggerChildren: 0 } },
};

const reducedItemVariants: Variants = {
  hidden: { opacity: 1 },
  visible: { opacity: 1 },
};

const addDefaultVariants = (variants: Variants) => ({
  hidden: { ...defaultItemVariants.hidden, ...variants.hidden },
  visible: { ...defaultItemVariants.visible, ...variants.visible },
});

function AnimatedGroup({
  children,
  className,
  variants,
  preset,
  as = "div",
  asChild = "div",
}: AnimatedGroupProps) {
  const shouldReduceMotion = useReducedMotion();

  const selectedVariants = {
    container: addDefaultVariants(defaultContainerVariants),
    item: addDefaultVariants(preset ? presetVariants[preset] : {}),
  };
  const containerVariants = shouldReduceMotion
    ? reducedContainerVariants
    : (variants?.container ?? selectedVariants.container);
  const itemVariants = shouldReduceMotion
    ? reducedItemVariants
    : (variants?.item ?? selectedVariants.item);

  const MotionComponent = motion(as);

  const MotionChild = motion(asChild);

  return (
    <MotionComponent
      animate="visible"
      className={className}
      initial="hidden"
      variants={containerVariants}
    >
      {React.Children.map(children, (child, index) => (
        <MotionChild
          // oxlint-disable-next-line react/no-array-index-key
          key={index}
          variants={itemVariants}
        >
          {child}
        </MotionChild>
      ))}
    </MotionComponent>
  );
}

export { AnimatedGroup };

import { motion, useReducedMotion } from "motion/react";
import type { ElementType, ReactNode } from "react";

interface AnimatedTextProps {
  as?: ElementType;
  children: ReactNode;
  className?: string;
  delay?: number;
}

export function AnimatedText({
  as: Tag = "span",
  children,
  className,
  delay = 0,
}: AnimatedTextProps) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.div
      animate={
        shouldReduceMotion
          ? { opacity: 1 }
          : { filter: "blur(0px)", opacity: 1, y: 0 }
      }
      initial={
        shouldReduceMotion
          ? { opacity: 1 }
          : { filter: "blur(12px)", opacity: 0, y: 12 }
      }
      transition={
        shouldReduceMotion
          ? { duration: 0 }
          : {
              bounce: 0.3,
              delay,
              duration: 1.5,
              type: "spring" as const,
            }
      }
    >
      <Tag className={className}>{children}</Tag>
    </motion.div>
  );
}

import PressButton from "@/components/elements/press-button";
import { Menu, X } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useState } from "react";

const menuItems = [
  { href: "#features", id: "features", name: "Features" },
  { href: "#pricing", id: "pricing", name: "Pricing" },
  { href: "#about", id: "about", name: "About" },
];

// Animation constants
const ANIMATION_DURATION = 0.2;
const STAGGER_DELAY = 0.05;
const EASE_OUT_QUART_X1 = 0.22;
const EASE_OUT_QUART_Y1 = 1;
const EASE_OUT_QUART_X2 = 0.36;
const EASE_OUT_QUART_Y2 = 1;
const EASE_OUT_QUART = [
  EASE_OUT_QUART_X1,
  EASE_OUT_QUART_Y1,
  EASE_OUT_QUART_X2,
  EASE_OUT_QUART_Y2,
] as const;
const ROTATION_ANGLE = 180;
const SCALE_MIN = 0;
const SCALE_MAX = 1;
const TRANSLATE_Y_OFFSET = -10;
const TRANSLATE_X_OFFSET = -10;

export const HeroHeader = () => {
  const shouldReduceMotion = useReducedMotion();
  const [menuState, setMenuState] = useState(false);

  return (
    <div className="relative">
      <header>
        <nav className="absolute top-0 left-0 z-20 w-full transition-all duration-300">
          <div className="mx-auto max-w-5xl px-6">
            <div className="relative flex flex-wrap items-center justify-between gap-6 py-6 transition-all duration-200 lg:gap-0">
              <div className="flex w-full justify-between gap-6 lg:w-auto">
                <a aria-label="DX UI home" className="flex items-center gap-2" href="/">
                  <img
                    alt=""
                    aria-hidden="true"
                    className="size-6"
                    draggable={false}
                    height={24}
                    src="/brand/dx-mark-128.webp"
                    width={24}
                  />
                  <span className="font-medium text-[15px] tracking-[-0.02em]">
                    DX <span className="text-muted-foreground">UI</span>
                  </span>
                </a>

                <button
                  aria-label={menuState === true ? "Close Menu" : "Open Menu"}
                  className="relative z-20 -m-2.5 -mr-4 block cursor-pointer p-2.5 lg:hidden"
                  onClick={() => setMenuState(!menuState)}
                  type="button"
                >
                  <AnimatePresence mode="wait">
                    {menuState ? (
                      <motion.div
                        animate={
                          shouldReduceMotion
                            ? { opacity: 1 }
                            : { opacity: 1, rotate: 0, scale: SCALE_MAX }
                        }
                        exit={
                          shouldReduceMotion
                            ? { opacity: 0, transition: { duration: 0 } }
                            : {
                                opacity: 0,
                                rotate: -ROTATION_ANGLE,
                                scale: SCALE_MIN,
                              }
                        }
                        initial={
                          shouldReduceMotion
                            ? { opacity: 1 }
                            : {
                                opacity: 0,
                                rotate: ROTATION_ANGLE,
                                scale: SCALE_MIN,
                              }
                        }
                        key="close"
                        transition={
                          shouldReduceMotion
                            ? { duration: 0 }
                            : {
                                duration: ANIMATION_DURATION,
                                ease: EASE_OUT_QUART,
                              }
                        }
                      >
                        <X className="m-auto size-6" />
                      </motion.div>
                    ) : (
                      <motion.div
                        animate={
                          shouldReduceMotion
                            ? { opacity: 1 }
                            : { opacity: 1, rotate: 0, scale: SCALE_MAX }
                        }
                        exit={
                          shouldReduceMotion
                            ? { opacity: 0, transition: { duration: 0 } }
                            : {
                                opacity: 0,
                                rotate: ROTATION_ANGLE,
                                scale: SCALE_MIN,
                              }
                        }
                        initial={
                          shouldReduceMotion
                            ? { opacity: 1 }
                            : {
                                opacity: 0,
                                rotate: -ROTATION_ANGLE,
                                scale: SCALE_MIN,
                              }
                        }
                        key="menu"
                        transition={
                          shouldReduceMotion
                            ? { duration: 0 }
                            : {
                                duration: ANIMATION_DURATION,
                                ease: EASE_OUT_QUART,
                              }
                        }
                      >
                        <Menu className="m-auto size-6" />
                      </motion.div>
                    )}
                  </AnimatePresence>
                </button>

                <div className="m-auto hidden size-fit lg:block">
                  <ul className="flex gap-1">
                    {menuItems.map((item) => (
                      <li key={item.id}>
                        <PressButton asChild size="sm" variant="ghost">
                          <a className="text-base" href={item.href}>
                            <span>{item.name}</span>
                          </a>
                        </PressButton>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>

              <AnimatePresence>
                {menuState ? (
                  <motion.div
                    animate={
                      shouldReduceMotion
                        ? { opacity: 1 }
                        : { opacity: 1, scale: SCALE_MAX, y: 0 }
                    }
                    className="mb-6 w-full flex-wrap items-center justify-end space-y-8 rounded-3xl border bg-background p-6 shadow-2xl shadow-zinc-300/20 md:flex-nowrap lg:m-0 lg:flex lg:w-fit lg:gap-6 lg:space-y-0 lg:border-transparent lg:bg-transparent lg:p-0 lg:shadow-none dark:shadow-none dark:lg:bg-transparent"
                    exit={
                      shouldReduceMotion
                        ? { opacity: 0, transition: { duration: 0 } }
                        : { opacity: 0, scale: 0.95, y: TRANSLATE_Y_OFFSET }
                    }
                    initial={
                      shouldReduceMotion
                        ? { opacity: 1 }
                        : { opacity: 0, scale: 0.95, y: TRANSLATE_Y_OFFSET }
                    }
                    transition={
                      shouldReduceMotion
                        ? { duration: 0 }
                        : {
                            duration: ANIMATION_DURATION,
                            ease: EASE_OUT_QUART,
                          }
                    }
                  >
                    <div className="lg:hidden">
                      <ul className="space-y-6 text-base">
                        {menuItems.map((item, index) => (
                          <motion.li
                            animate={
                              shouldReduceMotion
                                ? { opacity: 1 }
                                : { opacity: 1, x: 0 }
                            }
                            initial={
                              shouldReduceMotion
                                ? { opacity: 1 }
                                : { opacity: 0, x: TRANSLATE_X_OFFSET }
                            }
                            key={item.id}
                            transition={
                              shouldReduceMotion
                                ? { duration: 0 }
                                : {
                                    delay: index * STAGGER_DELAY,
                                    duration: ANIMATION_DURATION,
                                    ease: EASE_OUT_QUART,
                                  }
                            }
                          >
                            <a
                              className="block text-muted-foreground duration-150 hover:text-accent-foreground"
                              href={item.href}
                              onClick={() => setMenuState(false)}
                            >
                              <span>{item.name}</span>
                            </a>
                          </motion.li>
                        ))}
                      </ul>
                    </div>
                    <motion.div
                      animate={
                        shouldReduceMotion
                          ? { opacity: 1 }
                          : { opacity: 1, y: 0 }
                      }
                      className="flex w-full flex-col space-y-3 sm:flex-row sm:gap-3 sm:space-y-0 md:w-fit"
                      initial={
                        shouldReduceMotion
                          ? { opacity: 1 }
                          : { opacity: 0, y: 10 }
                      }
                      transition={
                        shouldReduceMotion
                          ? { duration: 0 }
                          : {
                              delay:
                                menuItems.length * STAGGER_DELAY +
                                STAGGER_DELAY,
                              duration: ANIMATION_DURATION,
                              ease: EASE_OUT_QUART,
                            }
                      }
                    >
                      <PressButton
                        onClick={() => setMenuState(false)}
                        size="sm"
                        type="button"
                        variant="ghost"
                      >
                        <span>Login</span>
                      </PressButton>
                      <PressButton
                        onClick={() => setMenuState(false)}
                        size="sm"
                        type="button"
                      >
                        <span>Sign Up</span>
                      </PressButton>
                    </motion.div>
                  </motion.div>
                ) : null}
              </AnimatePresence>
            </div>
          </div>
        </nav>
      </header>
    </div>
  );
};
